// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
/** A figure slide: title, the PNG scaled to fit, one line of reading under it. */
function figureSlide({ section, title, figure, reading, notes }) {
  const s = pres.addSlide({ masterName: "FIGURE", sectionTitle: section });
  s.addText(title, { placeholder: "title" });
  s.addImage({
    path: FIG(figure),
    x: 0.6, y: 1.35, w: 12.1, h: 4.85,
    sizing: { type: "contain", w: 12.1, h: 4.85 },
    objectName: figure,
  });
  s.addText(reading, { placeholder: "body" });
  if (notes) s.addNotes(notes);
  return s;
}

/** A row of big numbers. Each is {value, label}. */
function statRow(slide, stats, { y = 1.6, h = 1.9 } = {}) {
  const gap = 0.35;
  const w = (12.1 - gap * (stats.length - 1)) / stats.length;
  stats.forEach((st, i) => {
    const x = 0.6 + i * (w + gap);
    slide.addShape(pres.ShapeType.roundRect, {
      x, y, w, h, rectRadius: 0.08,
      fill: { color: C.background1 },
      line: { color: THEME.colors.accent1, width: 1 },
      objectName: `stat-${i}-card`,
    });
    slide.addText(st.value, {
      x, y: y + 0.18, w, h: 0.95, isTextBox: true, margin: 0,
      fontSize: 40, bold: true, color: THEME.colors.accent1, align: "center",
      objectName: `stat-${i}-value`,
    });
    slide.addText(st.label, {
      x: x + 0.15, y: y + 1.12, w: w - 0.3, h: 0.7, isTextBox: true, margin: 0,
      fontSize: 12, color: C.text2, align: "center",
      objectName: `stat-${i}-label`,
    });
  });
}

